#include <cuda_fp16.h>

extern "C" __device__
void dx_cp_async_pair(
        float* first,
        float* second,
        const float* source,
        long long first_index,
        long long second_index) {
    #pragma unroll
    for (int load = 0; load < 8; ++load) {
        constexpr int fp32_ld = 36;
        constexpr int rows_per_load = 4;
        const int row = threadIdx.x / 32 + load * rows_per_load;
        const int col = threadIdx.x % 32;
        const int shared_index = row * fp32_ld + col;
        unsigned first_shared = static_cast<unsigned>(
            __cvta_generic_to_shared(first + shared_index));
        unsigned second_shared = static_cast<unsigned>(
            __cvta_generic_to_shared(second + shared_index));
        const float* first_global = source + first_index + load * 2048;
        const float* second_global = source + second_index + load * 2048;
        asm volatile(
            "cp.async.ca.shared.global.L2::128B [%0], [%1], 4;\n"
            :: "r"(first_shared), "l"(first_global));
        asm volatile(
            "cp.async.ca.shared.global.L2::128B [%0], [%1], 4;\n"
            :: "r"(second_shared), "l"(second_global));
    }
    asm volatile("cp.async.commit_group;\n" ::);
}

extern "C" __device__
void dx_cp_async_half_tile(
        __half* destination,
        const __half* source,
        long long source_index) {
    constexpr int half_ld = 40;
    const int row = threadIdx.x >> 2;
    const int col = (threadIdx.x & 3) * 8;
    const int index = row * half_ld + col;
    unsigned destination_shared = static_cast<unsigned>(
        __cvta_generic_to_shared(destination + index));
    asm volatile(
        "cp.async.ca.shared.global.L2::128B [%0], [%1], 16;\n"
        :: "r"(destination_shared), "l"(source + source_index + index));
    asm volatile("cp.async.commit_group;\n" ::);
}

extern "C" __device__
void dx_cp_async_half_pair(
        __half* first,
        __half* second,
        const __half* source,
        long long first_index,
        long long second_index) {
    constexpr int half_ld = 40;
    const int row = threadIdx.x >> 2;
    const int col = (threadIdx.x & 3) * 8;
    const int index = row * half_ld + col;
    unsigned first_shared = static_cast<unsigned>(
        __cvta_generic_to_shared(first + index));
    unsigned second_shared = static_cast<unsigned>(
        __cvta_generic_to_shared(second + index));
    asm volatile(
        "cp.async.ca.shared.global.L2::128B [%0], [%1], 16;\n"
        :: "r"(first_shared), "l"(source + first_index + index));
    asm volatile(
        "cp.async.ca.shared.global.L2::128B [%0], [%1], 16;\n"
        :: "r"(second_shared), "l"(source + second_index + index));
    asm volatile("cp.async.commit_group;\n" ::);
}

extern "C" __device__
void dx_cp_async_bulk_half_triple(
        __half* first,
        __half* second,
        __half* third,
        const __half* source,
        long long first_index,
        long long second_index,
        long long third_index,
        unsigned long long* barriers) {
    unsigned barrier_shared = static_cast<unsigned>(
        __cvta_generic_to_shared(barriers));
    constexpr unsigned tile_bytes = 32 * 40 * sizeof(__half);
    constexpr unsigned transaction_bytes = 3 * tile_bytes;
    if (threadIdx.x == 0) {
        unsigned first_shared = static_cast<unsigned>(
            __cvta_generic_to_shared(first));
        asm volatile(
            "mbarrier.arrive.expect_tx.shared::cta.b64 _, [%0], %1;\n"
            :: "r"(barrier_shared), "r"(transaction_bytes) : "memory");
        asm volatile(
            "cp.async.bulk.shared::cta.global.mbarrier::complete_tx::bytes "
            "[%0], [%1], %2, [%3];\n"
            :: "r"(first_shared), "l"(source + first_index),
               "r"(tile_bytes), "r"(barrier_shared) : "memory");
    }
    if (threadIdx.x == 1) {
        unsigned second_shared = static_cast<unsigned>(
            __cvta_generic_to_shared(second));
        asm volatile(
            "cp.async.bulk.shared::cta.global.mbarrier::complete_tx::bytes "
            "[%0], [%1], %2, [%3];\n"
            :: "r"(second_shared), "l"(source + second_index),
               "r"(2 * tile_bytes), "r"(barrier_shared) : "memory");
    }
}

extern "C" __device__
void dx_async_bulk_init(unsigned long long* barriers) {
    if (threadIdx.x == 0) {
        unsigned barrier_shared = static_cast<unsigned>(
            __cvta_generic_to_shared(barriers));
        asm volatile(
            "mbarrier.init.shared::cta.b64 [%0], 1;\n"
            :: "r"(barrier_shared) : "memory");
    }
    __syncthreads();
}

extern "C" __device__
void dx_async_bulk_wait(
        unsigned long long* barriers,
        int phase) {
    if (threadIdx.x == 0) {
        unsigned barrier_shared = static_cast<unsigned>(
            __cvta_generic_to_shared(barriers));
        asm volatile(
            "{\n"
            ".reg .pred ready;\n"
            "DX_BULK_WAIT:\n"
            "mbarrier.try_wait.parity.shared::cta.b64 ready, [%0], %1;\n"
            "@ready bra DX_BULK_DONE;\n"
            "bra DX_BULK_WAIT;\n"
            "DX_BULK_DONE:\n"
            "}\n"
            :: "r"(barrier_shared), "r"(phase) : "memory");
    }
    __syncthreads();
}

extern "C" __device__
void dx_cp_async_wait() {
    asm volatile("cp.async.wait_group 0;\n" ::);
}
