__global__ void batch_lower_copy_kernel(
    const float* __restrict__ input,
    float* __restrict__ output,
    int n,
    int batch
) {
    const int total_rows = batch * n;
    const int warp = static_cast<int>(threadIdx.x) >> 5;
    const int lane = static_cast<int>(threadIdx.x) & 31;
    constexpr int warps_per_block = 8;
    for (int linear_row =
             static_cast<int>(blockIdx.x) * warps_per_block + warp;
         linear_row < total_rows;
         linear_row += static_cast<int>(gridDim.x) * warps_per_block) {
        const int row = linear_row % n;
        const long long base = static_cast<long long>(linear_row) * n;
        const int full_vectors = (row + 1) / 4;
        const float4* input_vectors = reinterpret_cast<const float4*>(
            input + base
        );
        float4* output_vectors = reinterpret_cast<float4*>(output + base);
        for (int vector = lane; vector < full_vectors;
             vector += 32) {
            output_vectors[vector] = input_vectors[vector];
        }
        const int tail = full_vectors * 4;
        for (int col = tail + lane; col <= row; col += 32) {
            output[base + col] = input[base + col];
        }
    }
